#[test]fn old_asset_json_byte_identical_roundtrip(){let text=r#"{"id":"asset1","path":"/tmp/a.wav","width":0,"height":0,"duration":2.0,"fps":0.0}"#;let old:kimo_core::model::Asset=serde_json::from_str(text).unwrap();assert_eq!(serde_json::to_string(&old).unwrap(),text);assert!(old.origin.is_none()&&old.hash.is_none()&&old.kind.is_none());let text=r#"{"origin":"import_samples","hash":"abc","kind":"audio","id":"asset1","path":"/tmp/a.wav","width":0,"height":0,"duration":2.0,"fps":0.0}"#;let new:kimo_core::model::Asset=serde_json::from_str(text).unwrap();assert_eq!(serde_json::to_string(&new).unwrap(),text);}
